/// Looks up a catalog entry by its canonical dot-separated `code`.
pub fn lookup_error_entry(code: &str) -> Option<&'static ErrorCatalogEntry> {
    let trimmed = code.trim();
    ERROR_CATALOG.iter().find(|entry| entry.code == trimmed)
}

/// Resolves a legacy/wire-protocol error code (or canonical code) to its canonical error code.
///
/// Matching is ASCII case-insensitive after trimming surrounding whitespace.
pub fn resolve_wire_alias(wire_code: &str) -> Option<&'static str> {
    let trimmed = wire_code.trim();
    if trimmed.is_empty() {
        return None;
    }
    for entry in ERROR_CATALOG {
        if entry.code.eq_ignore_ascii_case(trimmed)
            || entry
                .wire_aliases
                .iter()
                .any(|alias| alias.eq_ignore_ascii_case(trimmed))
        {
            return Some(entry.code);
        }
    }
    None
}

/// Resolves the localized Simplified Chinese (`zh-CN`) copy for `code` (or a wire alias)
/// with optional platform-specific overrides applied.
pub fn resolve_zh_cn_copy(code: &str, platform: ErrorPlatform) -> Option<ErrorCopy> {
    let entry = lookup_error_entry(code)
        .or_else(|| resolve_wire_alias(code).and_then(lookup_error_entry))?;
    let mut copy = entry.default_zh_cn;
    if platform != ErrorPlatform::Generic {
        if let Some(ov) = entry
            .zh_cn_overrides
            .iter()
            .find(|ov| ov.platform == platform)
        {
            if let Some(title) = ov.title {
                copy.title = title;
            }
            if let Some(message) = ov.message {
                copy.message = message;
            }
            if let Some(suggestion) = ov.suggestion {
                copy.suggestion = suggestion;
            }
        }
    }
    Some(copy)
}

/// Renders `{param}` placeholders in a copy template using a single-pass scan over `template`.
///
/// Replacement values are written directly to the output buffer and are never re-scanned,
/// preventing secondary placeholder expansion when a parameter value contains `{other}`.
pub fn render_copy_template(template: &str, params: &[(&str, &str)]) -> String {
    if params.is_empty() || !template.contains('{') {
        return template.to_string();
    }
    let mut out = String::with_capacity(template.len());
    let mut rest = template;
    while let Some(open_idx) = rest.find('{') {
        out.push_str(&rest[..open_idx]);
        let after_open = &rest[open_idx + 1..];
        let Some(close_idx) = after_open.find('}') else {
            out.push_str(&rest[open_idx..]);
            return out;
        };
        let key = &after_open[..close_idx];
        if let Some(nested_open) = key.find('{') {
            out.push('{');
            out.push_str(&key[..nested_open]);
            rest = &after_open[nested_open..];
            continue;
        }
        if let Some((_, value)) = params.iter().find(|(k, _)| *k == key) {
            out.push_str(value);
        } else {
            out.push('{');
            out.push_str(key);
            out.push('}');
        }
        rest = &after_open[close_idx + 1..];
    }
    out.push_str(rest);
    out
}
